import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guides/troubleshooting.md","filePath":"guides/troubleshooting.md","lastUpdated":1793726242000}'),n={name:"guides/troubleshooting.md"};function r(i,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>The failures people actually hit with this draft, what each one looks like, and what fixes it. Reason strings are listed in <a href="./../reference/errors">Error reasons</a>.</p><h2 id="pnpm-site-dev-before-pnpm-build" tabindex="-1"><code>pnpm site:dev</code> before <code>pnpm build</code> <a class="header-anchor" href="#pnpm-site-dev-before-pnpm-build" aria-label="Permalink to &quot;`pnpm site:dev` before `pnpm build`&quot;">​</a></h2><p><strong>Symptom.</strong> The dev server starts, but the shell at <code>/app/</code> fails to load: Vite reports that it cannot resolve an <code>@kernl/…</code> import, or the shell opens the preview with the notice &quot;Running the preview: The live shell could not start (…)&quot;.</p><p><strong>Cause.</strong> <code>apps/web</code> depends on the four packages with <code>workspace:^</code>, and each package&#39;s <code>exports</code> point at <code>dist/index.js</code>. A fresh clone has no <code>dist/</code>; <code>pnpm install</code> links the packages but does not build them.</p><p><strong>Fix.</strong> Build once, then start the site. Rebuild after changing a package.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site:dev</span></span></code></pre></div><h2 id="typedoc-fails-on-the-git-remote" tabindex="-1">TypeDoc fails on the git remote <a class="header-anchor" href="#typedoc-fails-on-the-git-remote" aria-label="Permalink to &quot;TypeDoc fails on the git remote&quot;">​</a></h2><p><strong>Symptom.</strong> <code>pnpm docs:api</code> (and therefore <code>pnpm docs:check</code> and <code>pnpm site:build</code>) stops with <code>The provided git remote &quot;origin&quot; was not valid. Source links will be broken</code>, raised to an error by <code>treatWarningsAsErrors</code> in <code>typedoc.json</code>.</p><p><strong>Cause.</strong> When neither <code>disableSources</code> nor <code>sourceLinkTemplate</code> is configured, TypeDoc derives source links from the remote named <code>origin</code> and warns when it is missing.</p><p><strong>Fix.</strong> The repository&#39;s <code>typedoc.json</code> sets <code>packageOptions.disableSources</code>, which makes TypeDoc skip the remote lookup; if you see the warning, check that a local change did not remove it. <code>entryPointStrategy</code> is <code>packages</code>, so command-line flags such as <code>--disableSources</code> do not reach the per-package converters; set options under <code>packageOptions</code>. Alternatively add the remote with <code>git remote add origin &lt;url&gt;</code>.</p><h2 id="localstorage-warnings-under-node-25-and-later" tabindex="-1"><code>localStorage</code> warnings under Node 25 and later <a class="header-anchor" href="#localstorage-warnings-under-node-25-and-later" aria-label="Permalink to &quot;`localStorage` warnings under Node 25 and later&quot;">​</a></h2><p><strong>Symptom.</strong> Running <code>pnpm test</code> prints <code>ExperimentalWarning: localStorage is not available because --localstorage-file was not provided.</code>, or a test that uses <code>localStorage</code> throws because it is <code>undefined</code>.</p><p><strong>Cause.</strong> Newer Node versions define a global <code>localStorage</code> that is empty unless Node is started with <code>--localstorage-file</code>. On Node 26, reading it prints the warning and returns <code>undefined</code>. kehto&#39;s shell persists its ACL and manifest cache through <code>localStorage</code>.</p><p><strong>Fix.</strong> Nothing, for the shipped suites: <code>packages/core/features/steps/world.ts</code> installs an in-memory <code>localStorage</code> when the global has no <code>getItem</code>, and the warning is harmless. In your own tests, pass a <code>StorageLike</code> (a <code>Map</code> behind <code>getItem</code>, <code>setItem</code> and <code>removeItem</code>) as <code>KernlHost.storage</code>, and install a stand-in before importing kehto if your test reaches its persistence.</p><h2 id="an-applet-opens-but-never-gets-past-its-first-screen" tabindex="-1">An applet opens but never gets past its first screen <a class="header-anchor" href="#an-applet-opens-but-never-gets-past-its-first-screen" aria-label="Permalink to &quot;An applet opens but never gets past its first screen&quot;">​</a></h2><p><strong>Symptom.</strong> The window shows the applet, which waits forever, shows its own &quot;not available&quot; state, or gets refusals.</p><p><strong>Cause.</strong> A domain the applet <code>requires</code> is not granted. kernl never grants a domain because an applet asked for it: the launcher shows the required domains as switches that start off, warns &quot;Without …, this applet may not work. You can still run it.&quot;, and <code>plan.missingRequired</code> names what is missing. The applet&#39;s <code>shell.init</code> lists only the baseline and the domains you turned on.</p><p><strong>Fix.</strong> Open the window&#39;s <strong>Grants</strong> panel and turn the domain on. The grant reaches the ACL at once, but the domains the applet was told about at mount do not change until it is opened again, so close the window and open the applet again. If the launcher instead says &quot;Could not open the applet (invalid:domain).&quot;, you switched on a domain this shell does not offer; turn that switch off and click <strong>Run</strong> again. A domain the shell does not offer has no switch in the grants panel (for example <code>config</code>, <code>intent</code> or <code>upload</code>; see <a href="./../concepts/architecture#where-each-nap-domain-is-served-from">Architecture</a>), and the applet cannot get it in kernl. A new build of an applet has a new hash, so it starts with no grants; see <a href="./../concepts/applets-under-kernl">Applets under kernl</a>.</p><h2 id="an-applet-was-quarantined" tabindex="-1">An applet was quarantined <a class="header-anchor" href="#an-applet-was-quarantined" aria-label="Permalink to &quot;An applet was quarantined&quot;">​</a></h2><p><strong>Symptom.</strong> A notice says &quot;… was stopped&quot;, the window shows &quot;This applet was stopped.&quot; with the reason <code>quarantine</code>, and the guard panel (<em>Guard · strict · N</em>) lists &quot;Applet … was quarantined: it kept flooding the shell&quot; (<code>flood:quarantine</code>) or &quot;…: too many web fetches while hidden&quot; (<code>flood:hidden-resource</code>).</p><p><strong>Cause.</strong> The applet sent more messages than the profile allows in the rolling window, or used up its <code>resource.*</code> allowance while hidden. The guard revokes the applet&#39;s binding and removes its frame; the guard state for that window is dropped.</p><p><strong>Fix.</strong> A stopped window does not restart. The window&#39;s <strong>Grants</strong> panel offers <strong>Release from quarantine</strong>, which calls <code>kernl.guard.release(windowId)</code> and clears the window&#39;s quarantine mark; to run the applet again, close the stopped window and open the applet again. It gets a fresh window and fresh guard counters, and its grants are unchanged, because quarantine does not block. If it floods again, either block it (<strong>Block applet</strong>) or, for an applet you trust, switch the guard panel&#39;s profile; that applies to every window and resets to <code>strict</code> on reload (<a href="./../how-tos/change-guard-profile">Change the guard profile</a>).</p>',23)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
